using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 changed the discriminator property from "Discriminator" to "$type".
            // Preserve the EF8 property name so existing 500K documents remain readable,
            // and direct SQL queries referencing c.Discriminator keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed id format from "EntityType|Key" to just "Key".
            // Preserve the EF8 format so existing documents are not orphaned.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonPropertyName("id");
            entity.UseETagConcurrency();
        });

        // EF Core 9 Cosmos provider no longer silently ignores HasIndex — it throws.
        // Cosmos DB indexes are managed via indexing policy, not EF model config.
        // Removed: entity.HasIndex(p => p.Sku);
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Preserve EF8 id format "EntityType|Key" for all entities so existing documents
        // written by EF8 remain accessible.
        configurationBuilder.Conventions.Add(_ =>
            new Microsoft.EntityFrameworkCore.Cosmos.Infrastructure.IdFormatConvention());
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

